        if (!n) { genSkip.push({ gen: f.genId, box: f.entity, why: 'empty-box' }); continue; }
        // 멱등 — 이미 채워진 제너레이터는 건너뛴다(플래그 없이 컴포넌트 상태로 판단).
        //   단, 상자를 지정해 «다시 그리라» 고 부른 경우(데이터가 새로 담긴 때)는 비우고 다시 채운다.
        if (gen.getLength && gen.getLength() > 0) {
            if (!boxId) { continue; }
            const had = gen.getLength();
            while (gen.getLength() > 0) { gen.removeChild(); }
            genCleared += had;
        }
        let row = 0;
        const cell = function (col) { const v = ds.getCellData(row, col); return (v === undefined || v === null) ? '' : v; };
        for (let i = 0; i < n; i++) {
            row = i;
            gen.insertChild(i);
            for (let c = 0; c < f.cells.length; c++) {
                const ch = gen.getChild(i, f.cells[c].childId);
                if (!ch || !ch.setValue) { continue; }
                ch.setValue(f.cells[c].fn(cell, i));
            }
            for (let k = 0; k < f.countIds.length; k++) {
                const cn = gen.getChild(i, f.countIds[k]);
                if (cn && cn.setValue) { cn.setValue(String(i + 1)); }
            }
            // 행 조건 — 마지막 행에만 보이는 자리.
            if (f.rowConds) {
                for (let rc = 0; rc < f.rowConds.length; rc++) {
                    const rn = gen.getChild(i, f.rowConds[rc].childId);
                    if (!rn) { continue; }
                    const show = (f.rowConds[rc].kind === 'last') ? (i === n - 1) : true;
                    if (rn.setStyle) { rn.setStyle('display', show ? '' : 'none'); }
                }
            }
        }
    }
    if (genSkip.length) {
        // 우리 계측이 읽는 자리 — 화면 동작에는 영향이 없다.
        scwin.genFillSkipped = genSkip;
    }
    if (genCleared) { scwin.genFillCleared = (scwin.genFillCleared || 0) + genCleared; }
};

/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_rowCopy = async function () {
    const rows = [{ childId: "ipt_scrnmode", fn: function () { return String(String((dma_pageContext.get("scrnmode") ?? ""))); } }];
    let copied = 0;
    for (let i = 0; i < rows.length; i++) {
        const it = rows[i];
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { /* TODO Stage2: [sdd] 행 복사 대상 부재:  it.childId */ continue; }
        try {
            const v = it.fn();
            if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); copied++; }
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); }
    }
    return copied;
};

/**
 * @method
 * @name init_disclosure
 * @description 초기화 — disclosure
 * @returns {void}
 * @hidden N
 */
scwin.init_disclosure = function () {
    $("div.temp-contents").empty();
    $("div.temp-contents").load('/external/dse/main/main_contents.htm?_=' + new Date().getTime(), function() {
            /* TODO Stage2: [sdd] 미실현 동작: set_visible (대상 미해석) — 전환 미완 */ /* unresolved-target intent:set_visible — {target}.setStyle({args}) */
            $("section.main-important #main-today-1 article").html($("div.temp-contents #main-today-1 article").html());
            $("section.main-important #main-today-2 article").html($("div.temp-contents #main-today-2 article").html());
            $("section.main-important #main-today-3 article").html($("div.temp-contents #main-today-3 article").html());
    });
};

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {void}
 * @hidden N
 */
scwin.init_pageBody = function () {
    try {
        $('section.latest_disclosures li:first').addClass("active");
        if ($c.util.getComponent('ipt_scrnmode').getValue() === "3") {
            $('section.valueup').addClass("active");
            $('section.valueup li:first').addClass("active");
        } else {
            $('section.latest_disclosures').addClass("active");
        }
        const detail_search_opt = { btn: "header.container section.search a.more", close: "a.btn-pop-close", handle: "hgroup.handle", e: "click" };
        $('section.detail_search.popup').dim_dialog(detail_search_opt);
        scwin.sitemap_init();
        scwin.mainImportant_init();
        bt_util_init();
        scwin.gnb_init();
        $('section.news_spot article.stockindex ul').simple_slideshow5({ interval: 1500 });
        scwin.openDisclaimerPopup();
        $('.overlay-image').each(function() {
                $(this).bind("mouseover focus", function() {
                        $(this).addClass('active');
                });
                $(this).bind("mouseleave focusout", function() {
                        $(this).removeClass('active');
                });
        });

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jlddst90000.onpageload' }); }
};

