/**
 * @method
 * @name mainImportant_init
 * @description main Important init 처리
 * @returns {void}
 * @hidden N
 */
scwin.mainImportant_init = function () {
    $('section.main-important a.bm').bind("mouseover focus", function() {
            $('section.main-important section.wrapper').removeClass("active");
            let oc = $(this).attr("class");
            oc = oc.replace(" bm", "");
            $('section.main-important section.' + oc + ".wrapper").addClass("active");
    });
    $('section.main-important a.mm').bind("mouseover focus", function() {
            $(this).parent().parent().children("li").removeClass("active");
            $(this).parent().addClass("active");
    });
};

/**
 * @method
 * @name leadingZeros
 * @description leading Zeros 처리
 * @param {Number} n n
 * @param {*} digits digits
 * @returns {void}
 * @hidden N
 */
scwin.leadingZeros = function (n, digits) {
    let zero = '';
    n = n.toString();
    if (n.length < digits) {
        for (i = 0; i < digits - n.length; i++) {
            zero += '0';
        }
    }
    return zero + n;
};

