 */
scwin.bt_util_img_re = function () {
    $('nav.bt_util ul.menu li').each(function() {
            const target = $(this).children("a");
            target.children("img").attr("src", target.children("img").attr("src").replace(target.data("rname"), target.data("oname")));
    });
};

/**
 * @method
 * @name gnb_init
 * @description gnb init 처리
 * @returns {void}
 * @hidden N
 */
scwin.gnb_init = function () {
    $('#gnb li').each(function() {
            $(this).children("a.nm").bind("mouseover focus", function() {
                    $(this).children("span").children("img").fadeOut(600);
            });
            $(this).children("a.nm").bind("mouseleave focusout", function() {
                    $(this).children("span").children("img").fadeIn(600);
            });
    });
};

/**
 * @method
 * @name fnTopNoticeOpen
 * @description fn Top Notice Open 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnTopNoticeOpen = async function () {
    if (nCnt === 0) {
        await $c.win.alert("표시할 공지사항이 없습니다.");
        return;
    }
    $('section#topnotice article.ctt li:first').addClass("first");
    const style = $('#topnotice').attr("style");
    let bgpy = $('#topnotice').height() + "px";
    if (style.search("block") > 0) {
        bgpy = "0px";
    }
    setTimeout(function() {
            $('#topnotice').slideToggle(200);
            $("body").animate({ 'background-position-y': bgpy }, 200);
            if (nCnt > 1) {
                const slider_notice = $('.bxslider-notice').bxSlider({ mode: "fade", auto: true, speed: 200, autoControls: true });
            }
        }, 200);
};

