/**
 * @method
 * @name activeImgname
 * @description active Imgname 처리
 * @param {*} src src
 * @returns {void}
 * @hidden N
 */
scwin.activeImgname = function (src) {
    const data = {  };
    const hover_str = "_active";
    const tmp = src.split("/");
    const ext = /^.+\.([^.]+)$/.exec(tmp[3]);
    data.filename = tmp[3].replace("." + ext[1], "");
    data.rov_filename = data.filename + hover_str + "." + ext[1];
    data.filename = data.filename + "." + ext[1];
    return data;
};

/**
 * @method
 * @name sitemap_init
 * @description sitemap init 처리
 * @returns {void}
 * @hidden N
 */
scwin.sitemap_init = function () {
    if ($('section.sitemap').length < 1) {
        return;
    }
    $('a.btn.sitemap.open').bind("click focus", function(e) {
            e.preventDefault();
            if (cnt === 0) {
                $(this).addClass('hide');
                cnt = 1;
                setTimeout(function() {
                        $('section.sitemap').slideToggle(400);
                    }, 200);
            } else {
                if (cnt === 1) {
                    setTimeout(function() {
                            $('section.sitemap').slideToggle(400);
                        }, 200);
                    setTimeout(function() {
                            $('a.btn.sitemap.open').removeClass('hide');
                        }, 400);
                    cnt = 0;
                }
            }
    });
    $('a.btn_sitemap-close').bind("click", function(e) {
            e.preventDefault();
            setTimeout(function() {
                    $('section.sitemap').slideToggle(400, function() {
                            cnt = 0;
                            $('a.btn.sitemap.open').removeClass('hide');
                    });
                }, 100);
    });
    $('section.sitemap a.first').bind("mouseover focus", function() {
            $('section.sitemap article').removeClass("active");
            $(this).parent().addClass("active");
            $(this).parent().parent().parent().addClass("active");
    });
    $('section.sitemap a.first').bind("mouseout focusout", function() {
            $(this).parent().removeClass("active");
    });
    $('section.sitemap span , section.sitemap input[type=checkbox]').bind("mouseover focus", function() {
            $('section.sitemap article').removeClass("active");
            $(this).parent().parent().addClass("active");
            $(this).parent().parent().parent().parent().addClass("active");
    });
    $('section.sitemap span , section.sitemap input[type=checkbox]').bind("mouseout focusout", function() {
            $(this).parent().parent().removeClass("active");
    });
    $('section.sitemap article').bind("mouseleave focusout", function() {
            $(this).removeClass("active");
    });
    $('section.sitemap a.btn_sitemap-set').click(function(e) {
            e.preventDefault();
            if (!$('section.sitemap').hasClass("chkon")) {
                /* TODO Stage2: [sdd] 미실현 동작: set_visible (대상 미해석) — 전환 미완 */ /* unresolved-target intent:set_visible — {target}.setStyle({args}) */
                /* TODO Stage2: [sdd] 미실현 동작: set_visible (대상 미해석) — 전환 미완 */ /* unresolved-target intent:set_visible — {target}.setStyle({args}) */
                $('section.sitemap').addClass("chkon");
                $(this).children("img").attr("src", $(this).children("img").attr("src").replace("_set", "_active"));
                $(this).children("img").attr("alt", "확인");
            } else {
                fnSetCookieMyMenu();
                /* TODO Stage2: [sdd] 미실현 동작: set_visible (대상 미해석) — 전환 미완 */ /* unresolved-target intent:set_visible — {target}.setStyle({args}) */
                /* TODO Stage2: [sdd] 미실현 동작: set_visible (대상 미해석) — 전환 미완 */ /* unresolved-target intent:set_visible — {target}.setStyle({args}) */
                $('section.sitemap').removeClass("chkon");
                $(this).children("img").attr("src", $(this).children("img").attr("src").replace("_active", "_set"));
                $(this).children("img").attr("alt", "설정");
            }
    });
    try {
        if ($.browser.msie && $.browser.version === "7.0") {
            $('div.gnb1-wrapper').css("top", -3);
        }
        const btnMore = $('div.gnb1-wrapper');
        const imgArrow = $('#sub nav#gnb1 div.lnb div.wrapper img.arrow');
        $('section.sitemap a.first').bind("mouseover focus", function() {
                fnSubClose(btnMore, -1);
        });
        $('section.sitemap article li a.more').each(function(i) {
                $(this).bind("mouseover focus", function() {
                        $(this).parent().addClass("active");
                        $(this).parent().parent().parent().addClass("active");
                        $(this).children("span").children("img").attr("src", "../images/common/bg_gnb_gmn2_active.gif");
                        fnSubClose(btnMore, i);
                        const left1 = $(this).parent().offset().left;
                        const left2 = $(this).children("span").children("img").offset().left;
                        let leftVal = left2 - left1 - 2;
                        if (i === 7) {
                            leftVal = leftVal - 6;
                        }
                        imgArrow.eq(i).css("left", leftVal);
                        /* TODO Stage2: [sdd] 미실현 동작: set_visible (대상 미해석) — 전환 미완 */ /* unresolved-target intent:set_visible — {target}.setStyle({args}) */
                });
                btnMore.eq(i).bind("mouseleave", function() {
                        /* TODO Stage2: [sdd] 미실현 동작: set_visible (대상 미해석) — 전환 미완 */ /* unresolved-target intent:set_visible — {target}.setStyle({args}) */
                });
                $(this).bind("mouseout focusout", function() {
                        $(this).parent().removeClass("active");
                        $(this).children("span").children("img").attr("src", "../images/common/bg_gnb_gmn2.gif");
                });
        });
    } catch (e) { $c.exception.handleError(e, { notify: 'none', context: 'jlddst90000' });
        console.error(e.message);
    }
};

